import{_ as t,o as i,c as n,a2 as a}from"./chunks/framework.Cm6XCzck.js";const p=JSON.parse('{"title":"RCR-20260831 公开证据包：Runtime 连续性、重试资格与可采纳证据","description":"","frontmatter":{"title":"RCR-20260831 公开证据包：Runtime 连续性、重试资格与可采纳证据","date":"2026-08-31","column":"research-evidence","category":"evidence","article_type":"evidence-pack","edition":"research-center","summary":"三篇 Runtime 连续性研究共用的脱敏捕获数据、Reader、检查器和来源映射：重试资格、跨 Session 授权与归属、以及分时证据可采纳性。","lifecycle":"Published","publication_authorized":true},"headers":[],"relativePath":"zh/research/evidence/2026-08-31-runtime-continuity.md","filePath":"zh/research/evidence/2026-08-31-runtime-continuity.md","lastUpdated":1788166937000}'),r={name:"zh/research/evidence/2026-08-31-runtime-continuity.md"};function s(o,e,d,c,l,u){return i(),n("div",null,[...e[0]||(e[0]=[a(`<p><a href="/joinwell52/en/research/evidence/2026-08-31-runtime-continuity">English Version</a></p><h1 id="rcr-20260831-runtime-连续性研究证据包" tabindex="-1">RCR-20260831｜Runtime 连续性研究证据包 <a class="header-anchor" href="#rcr-20260831-runtime-连续性研究证据包" aria-label="Permalink to &quot;RCR-20260831｜Runtime 连续性研究证据包&quot;">​</a></h1><p>状态：公开审阅与复核包。所有身份均为实验合成标识；不含真实任务账本、凭据、签名密钥或产品源码。</p><p>本页支持三篇文章：</p><ol><li><a href="/joinwell52/zh/engineering/2026-08-31-audit-failure-retry">审计失败后的重试资格</a></li><li><a href="/joinwell52/zh/engineering/2026-08-31-session-principal-continuity">跨 Session 的授权、执行身份与归属</a></li><li><a href="/joinwell52/zh/engineering/2026-08-31-audit-evidence-admissibility">Runtime 的可采纳证据实验</a></li></ol><h2 id="复核层次" tabindex="-1">复核层次 <a class="header-anchor" href="#复核层次" aria-label="Permalink to &quot;复核层次&quot;">​</a></h2><p><strong>公开捕获数据与 Reader。</strong> 只需 Node.js、无需网络或产品依赖；可检查文章数字、四个时点与四个负对照。</p><p><strong>产品行为重跑。</strong> 需要获准访问固定 CodeFlowMu 源码和已安装依赖；探针调用真实服务，但仅使用本地合成执行器。它不验证真实 HTTP、Git、Issue、支付或 provider 账号切换。</p><p>下载下列文件到同一目录后运行：</p><ul><li><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/check.mjs">检查器</a></li><li><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/reader.mjs">Reader</a></li><li><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/check-manifest.mjs">完整性检查器</a></li><li><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/fixtures/timeline.json">时间线 Fixture</a>（其余 Fixture 同目录）</li><li><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/provenance.json">来源与版本</a></li><li><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/manifest.json">清单</a></li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node check.mjs</span></span>
<span class="line"><span>node check-manifest.mjs</span></span></code></pre></div><p>预期退出码为 0。公开检查确认 3 组跨进程恢复对照、11 组授权消费、8 组技能绑定、8 个 Reader 场景和 CatchBench PRE 的 1,187 个配置计数。不同集合不能相加成产品可靠性、检测准确率或线上收益。</p><h2 id="主张-→-来源-→-fixture-→-check" tabindex="-1">主张 → 来源 → Fixture → Check <a class="header-anchor" href="#主张-→-来源-→-fixture-→-check" aria-label="Permalink to &quot;主张 → 来源 → Fixture → Check&quot;">​</a></h2><table tabindex="0"><thead><tr><th>证据</th><th>支持的主张</th><th>公开附件</th><th>能证明什么，不能证明什么</th></tr></thead><tbody><tr><td>E-A0</td><td>P0–P3 在不同审计落点的状态与效果不同</td><td><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/fixtures/historical-probes.json">historical-probes.json</a></td><td>P3 保留首次效果而被写成 failed；不是线上事故率</td></tr><tr><td>E-A1</td><td>新进程恢复的效果取决于执行器去重和摘要</td><td><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/fixtures/restart.json">restart.json</a></td><td>无去重为 1→2，稳定键为 1→1，摘要变化拒绝；不是全部生产执行器覆盖</td></tr><tr><td>E-B1</td><td>session 变化本身不足以使匹配批准失效</td><td><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/fixtures/authorization.json">authorization.json</a></td><td>11 条条件、两条允许路径不能二次消费；不证明外部入口身份可信</td></tr><tr><td>E-B2</td><td>会话绑定、错误声明与合法无会话操作分类</td><td><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/fixtures/session-binding.json">session-binding.json</a></td><td>2 verified、5 invalid_claim、1 not_applicable；公开包不携带 HMAC 密钥</td></tr><tr><td>E-C0</td><td>CatchBench PRE 的总体与来源分布</td><td><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/fixtures/catchbench-pre.log">原始输出</a></td><td>固定 PRE 输出及 1,187 配置；不是本轮模型调用或 CodeFlowMu 成绩</td></tr><tr><td>E-C1</td><td>命题、归属、时点、完整性改变可采纳证据</td><td><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/fixtures/timeline.json">timeline.json</a></td><td>Reader 跑 4 正常/4 负对照；不是产品审计器或统计准确率</td></tr></tbody></table><h2 id="证据读取合同与限制" tabindex="-1">证据读取合同与限制 <a class="header-anchor" href="#证据读取合同与限制" aria-label="Permalink to &quot;证据读取合同与限制&quot;">​</a></h2><p>公开 Reader 固定 proposition，接受正确 owner、未超过 cutoff、且与 manifest 匹配的内容；然后读取截止点内最新的效果快照。因此它检查的是可采纳证据，不是全部日志。<code>unknown</code> 不等于 <code>false</code>，<code>not_observed</code> 不等于未来不会发生。</p><p>原始产品探针与本次执行一致的 <a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/reproduce-product.mts">reproduce-product.mts</a> 也随包提供。它要求源码固定在 <code>f0f42f01c8f6d55bfe3d32e108f607841a2900d9</code>，并且只能写入隔离研究目录。</p><p>本轮实验由同一研究者完成；没有独立 QA、盲测、生产故障率、真实 provider 账号权限提升或线上预警效果结论。公开清单可发现相对于本包的静默改动，但不是独立见证。</p>`,18)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
